int main() {
    double weight;
    int zone;
    cout << "Weight: ";
    cin >> weight;
    cout << "Zone: ";
    cin >> zone;
    double rate;
    if (zone == 1) {
        rate = 2.00;
    } else if (zone == 2) {
        rate = 3.00;
    } else if (zone == 3) {
        rate = 4.50;
    } else {
        cout << "Invalid zone" << endl;
        return 0;
    }
    double cost = weight * rate;
    if (weight > 20) {
        cost += 5.00;
    }
    cout << fixed << setprecision(2) << "Cost: $" << cost << endl;
    return 0;
}

