#include <iomanip>
#include <iostream>
using namespace std;

// Author: Ada Example
int main() {
    double temp;
    char unit;
    cout << "Temperature: ";
    cin >> temp;
    cout << "Unit (C or F): ";
    cin >> unit;
    double fahrenheit;
    if (unit == 'C') {
        fahrenheit = temp * 9 / 5 + 32;
        cout << fixed << setprecision(1) << fahrenheit << " F" << endl;
    } else if (unit == 'F') {
        fahrenheit = temp;
        cout << fixed << setprecision(1) << (temp - 32) * 5 / 9 << " C" << endl;
    } else {
        cout << "Invalid unit" << endl;
        return 0;
    }
    if (fahrenheit <= 32) {
        cout << "Freezing" << endl;
    }
    return 0;
}

